namespace seed_b_backend.Api.Controllers;

[ApiController]
[Route("api/products")]
public class ProductsController(ProductQueryService service) : ControllerBase
{
    [HttpGet]
    public async Task<IActionResult> GetProducts([FromQuery] int page = 1, [FromQuery] string? categoryId = null, [FromQuery] string? subcategoryId = null, [FromQuery] string? sortBy = null, [FromQuery] string? sortDirection = null)
