import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

import { PagedResult, ProductListItem, ProductSortBy, ProductSortDirection } from '../models/product.model';

@Injectable({ providedIn: 'root' })
export class ProductService {
  private readonly http = inject(HttpClient);

  getProducts(
    page: number,
    categoryId?: string | null,
    subcategoryId?: string | null,
    sortBy?: ProductSortBy,
    sortDirection?: ProductSortDirection
  ): Observable<PagedResult<ProductListItem>> {
    let params = new HttpParams().set('page', page);
    if (categoryId) {
      params = params.set('categoryId', categoryId);
    }
    if (subcategoryId) {
      params = params.set('subcategoryId', subcategoryId);
    }
    if (sortBy) {
      params = params.set('sortBy', sortBy);
    }
    if (sortDirection) {
      params = params.set('sortDirection', sortDirection);
    }
    return this.http.get<PagedResult<ProductListItem>>('/api/products', { params });
  }
}

